switch (trans.TransType)
{
    case TransType.Receipt when trans.Stage == TransStage.Physical:
    case TransType.Adjustment when trans.Stage == TransStage.Physical:
        onHand.PhysicalQty += trans.Qty;
        break;
    case TransType.Issue when trans.Stage == TransStage.Physical:
        onHand.PhysicalQty -= trans.Qty;
        break;
    case TransType.Issue when trans.Stage == TransStage.Deducted:
    case TransType.Adjustment when trans.Stage == TransStage.Deducted:
        onHand.PhysicalQty -= trans.Qty;
        break;
    case TransType.Transfer when trans.Stage == TransStage.Deducted:
        onHand.PhysicalQty -= trans.Qty;
        break;
    case TransType.Transfer when trans.Stage == TransStage.Physical:
        onHand.PhysicalQty += trans.Qty;
        break;
}

