public class UomService(IAppDbContext context) : IUomService
{
    public async Task<decimal> ConvertAsync(Guid fromUomId, Guid toUomId, decimal quantity, CancellationToken ct = default)
    {
        if (fromUomId == toUomId) return quantity;
        var conversion = await context.UomConversions.AsNoTracking()
            .FirstOrDefaultAsync(x => x.FromUomId == fromUomId && x.ToUomId == toUomId, ct);
        if (conversion != null) return quantity * conversion.ConversionFactor;
        var reverseConversion = await context.UomConversions.AsNoTracking()
            .FirstOrDefaultAsync(x => x.FromUomId == toUomId && x.ToUomId == fromUomId, ct);
        if (reverseConversion != null && reverseConversion.ConversionFactor != 0)
            return quantity / reverseConversion.ConversionFactor;
        throw BusinessRule.UomConversions.NotFound.ToBusinessException([$"{fromUomId}", $"{toUomId}"]);
    }
}

