public class OnHandConfiguration : IEntityTypeConfiguration<OnHand>
{
    public void Configure(EntityTypeBuilder<OnHand> builder)
    {
        builder.ToTable("on_hand", DatabaseConstants.Schemas.Inventory);
        builder.ConfigureTenantDefault();
        builder.Property(e => e.PhysicalQty).HasColumnName("physical_qty").HasPrecision(18, 4);
        builder.Property(e => e.ReservedQty).HasColumnName("reserved_qty").HasPrecision(18, 4);
        builder.Property(e => e.AllocatedQty).HasColumnName("allocated_qty").HasPrecision(18, 4);
        builder.HasIndex(e => new { e.TenantId, e.ItemId, e.InventDimId }).IsUnique();
    }
}
